import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._next_id = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(
        self, customer: str, title: str, priority: str = "normal"
    ) -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        ticket_id = self._next_id
        self._next_id += 1
        rank = len(self.PRIORITIES) - 1 - self.PRIORITIES.index(priority)
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "rank": rank,
            "status": "queued",
        }
        heapq.heappush(self._queue, (rank, ticket_id))
        return ticket_id

    def next_ticket(self) -> int | None:
        """Take the next ticket out of the queue, or return None."""
        while self._queue:
            _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["status"] == "queued":
                ticket["status"] = "in progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("A closed ticket cannot be reopened")
        if ticket["status"] != "queued":
            ticket["status"] = "queued"
            heapq.heappush(self._queue, (ticket["rank"], ticket_id))
